-- a1h t09 probe: does Assemble_Fleet of ground units on a planet's surface launch them into the fleet (orbit)?
-- Galactic story script of the campaign "A1H PROBE: ASSEMBLE FLEET" (human = Empire), generated by
-- tools/probe_mod/a1h_assemble_fleet/build_a1h_mod.py from a1h_story.lua. The script runs by itself:
--   when the story event A1H_Begin fires (3 s after the galaxy starts) it runs four cases one after another:
--     C  the Empire's Starting_Forces infantry on Tatooine's surface (human, never spawned by Lua)
--     A  Empire ground units spawned by SpawnList on Abregado Rae (human)
--     B  Underworld ground units spawned on Byss (AI player None, the shipped story pattern)
--     D  a mixed list on Tatooine after C: a spawned Empire ship (orbit) + a spawned Empire infantry squad (surface)
--   Each case: spawn (or find), wait 3 s, record every unit's parent and planet, Assemble_Fleet, record the fleet and
--   every unit again, wait 10 s, record again, then show the verdict on screen (Game_Message TEXT_A1H_<case>_<verdict>).
-- Output: Lua strings "A1HR|<kind>|n=..|...|END" kept alive in A1H_REC (a1h_run.py finds them by scanning the game's
-- memory; retail _CustomScriptMessage / _MessagePopup show nothing) and the on-screen Game_Message lines.
-- Read-only apart from the spawned units: no orders, no Move_To, no Invade.
require("PGStoryMode")

A1H_REC = {}
A1H_N = 0

function A1H_Rec(kind, text)
	A1H_N = A1H_N + 1
	local s = "A1HR|" .. kind .. "|n=" .. A1H_N .. "|" .. text .. "|END"
	A1H_REC[A1H_N] = s
	pcall(_MessagePopup, s)
end

function A1H_Say(text_id)
	A1H_Rec("SAY", "text=" .. text_id)
	pcall(Game_Message, text_id)
end

function Definitions()
	StoryModeEvents = { A1H_Begin = A1H_State_Begin }
	A1H_Started = false
end

function A1H_State_Begin(message)
	if message == OnEnter and not A1H_Started then
		A1H_Started = true
		Create_Thread("A1H_Run")
	end
end

-- Type name of an object (planets give the planet name, fleets the fleet type), "nil" / "?" when not available.
function A1H_Name(o)
	if o == nil then return "nil" end
	local okv, valid = pcall(TestValid, o)
	if okv and not valid then return "nil" end
	local ok, n = pcall(function() return o.Get_Type().Get_Name() end)
	if ok and n ~= nil then return tostring(n) end
	return "?"
end

function A1H_Parent(u)
	local ok, p = pcall(function() return u.Get_Parent_Object() end)
	if ok then return p end
	return nil
end

function A1H_Planet(u)
	local ok, p = pcall(function() return u.Get_Planet_Location() end)
	if ok then return p end
	return nil
end

function A1H_Count(o)
	local ok, n = pcall(function() return o.Get_Contained_Object_Count() end)
	if ok and n ~= nil then return tostring(n) end
	return "?"
end

function A1H_Describe(kind, case, units, fleet)
	local fleet_name = A1H_Name(fleet)
	local inside, total = 0, 0
	for i, u in pairs(units) do
		total = total + 1
		local parent = A1H_Parent(u)
		local pn = A1H_Name(parent)
		if fleet ~= nil and pn == fleet_name then inside = inside + 1 end
		A1H_Rec(kind, "case=" .. case .. "|i=" .. i .. "|type=" .. A1H_Name(u) .. "|parent=" .. pn ..
			"|parent_count=" .. A1H_Count(parent) .. "|planet=" .. A1H_Name(A1H_Planet(u)))
	end
	return inside, total
end

function A1H_Case(case, player_name, planet_name, units)
	local planet = FindPlanet(planet_name)
	A1H_Rec("CASE", "case=" .. case .. "|player=" .. player_name .. "|planet=" .. A1H_Name(planet) ..
		"|units=" .. table.getn(units))
	if table.getn(units) == 0 then
		A1H_Rec("VERDICT", "case=" .. case .. "|verdict=NOUNITS|total=0")
		A1H_Say("TEXT_A1H_" .. case .. "_NOUNITS")
		return
	end
	Sleep(3)
	A1H_Describe("BEFORE", case, units, nil)
	local ok, fleet = pcall(Assemble_Fleet, units)
	if not ok or fleet == nil or not TestValid(fleet) then
		A1H_Rec("ASSEMBLE", "case=" .. case .. "|fleet=nil|err=" .. tostring(fleet))
		A1H_Rec("VERDICT", "case=" .. case .. "|verdict=NOFLEET|total=" .. table.getn(units))
		A1H_Say("TEXT_A1H_" .. case .. "_NOFLEET")
		return
	end
	A1H_Rec("ASSEMBLE", "case=" .. case .. "|fleet=" .. A1H_Name(fleet) .. "|count=" .. A1H_Count(fleet) ..
		"|parent=" .. A1H_Name(A1H_Parent(fleet)) .. "|planet=" .. A1H_Name(A1H_Planet(fleet)))
	local inside, total = A1H_Describe("AFTER", case, units, fleet)
	Sleep(10)
	local later_inside = A1H_Describe("LATER", case, units, fleet)
	A1H_Rec("FLEET_LATER", "case=" .. case .. "|valid=" .. tostring(TestValid(fleet)) .. "|count=" .. A1H_Count(fleet) ..
		"|planet=" .. A1H_Name(A1H_Planet(fleet)))
	local verdict = "NOT_LAUNCHED"
	if inside == total and later_inside == total then
		verdict = "LAUNCHED"
	elseif inside > 0 or later_inside > 0 then
		verdict = "PARTIAL"
	end
	A1H_Rec("VERDICT", "case=" .. case .. "|verdict=" .. verdict .. "|inside=" .. inside .. "|later=" .. later_inside ..
		"|total=" .. total)
	A1H_Say("TEXT_A1H_" .. case .. "_" .. verdict)
end

-- Every object of `type_name` owned by `player` (Find_All_Objects_Of_Type with a type-name filter; owner checked here).
function A1H_Find(type_name, player)
	local out = {}
	local ok, all = pcall(Find_All_Objects_Of_Type, type_name)
	if not ok or all == nil then return out end
	for _, o in pairs(all) do
		local okp, owner = pcall(function() return o.Get_Owner() end)
		if okp and owner == player then table.insert(out, o) end
	end
	return out
end

function A1H_Run()
	A1H_Say("TEXT_A1H_STORY_LUA")
	local empire = Find_Player("Empire")
	local uw = Find_Player("Underworld")
	if empire == nil or uw == nil then
		A1H_Rec("ERR", "why=player missing")
		return
	end
	A1H_Case("C", "Empire", "Tatooine", A1H_Find("Imperial_Stormtrooper_Squad", empire))
	A1H_Case("A", "Empire", "Abregado_Rae",
		SpawnList({ "Imperial_Heavy_Scout_Squad", "Imperial_Stormtrooper_Squad" }, FindPlanet("Abregado_Rae"), empire, false, false))
	A1H_Case("B", "Underworld", "Byss",
		SpawnList({ "Underworld_Merc_Squad", "Underworld_Merc_Squad" }, FindPlanet("Byss"), uw, false, false))
	A1H_Case("D", "Empire", "Tatooine",
		SpawnList({ "Tartan_Patrol_Cruiser", "Imperial_Stormtrooper_Squad" }, FindPlanet("Tatooine"), empire, false, false))
	A1H_Rec("DONE", "records=" .. A1H_N)
	A1H_Say("TEXT_A1H_DONE")
end
